import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.76ZGnlPi.js";const u=JSON.parse('{"title":"Custom Markup Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"admin/custom-markup/index.md","filePath":"admin/custom-markup/index.md"}'),n={name:"admin/custom-markup/index.md"};function o(r,t,d,l,p,c){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="custom-markup-management-guide" tabindex="-1">Custom Markup Management Guide <a class="header-anchor" href="#custom-markup-management-guide" aria-label="Permalink to &quot;Custom Markup Management Guide&quot;">​</a></h1><p>This guide explains how administrators configure <strong>custom markup rules</strong> for the custom-ota / custom-booking product line.</p><blockquote><p><strong>Status:</strong> Custom markup is wired into custom-ota / custom-booking pricing <strong>for BUSINESS class only</strong> (owner 2026-06-15). A BUSINESS-class fare is priced as <code>raw supplier base + custom markup + custom tax</code>, with <strong>no strikethrough</strong> (<code>originalPrice = 0</code>) and fare type <code>STANDARD</code>. <strong>ECONOMY (and any non-business) class is unaffected</strong> — it keeps the per-route reducer and the retail strikethrough; custom markup is never applied to it. A markup rule scoped to a non-business class (or to no class) therefore only takes effect on the BUSINESS legs that also match its route scope.</p></blockquote><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Configure flat markup rules for custom bookings, independent of the OTA pricing engine</td></tr><tr><td><strong>Scope</strong></td><td>Optional per-route (<code>originId</code> / <code>destinationId</code> / <code>tripClass</code> / <code>tripType</code>) or global default</td></tr><tr><td><strong>Markup Types</strong></td><td>Percentage (e.g. 15%) or Fixed amount (SAR / IDR)</td></tr><tr><td><strong>Selection</strong></td><td>Most route-specific active rule wins; ties broken by priority (highest first)</td></tr></tbody></table><p>This is <strong>separate</strong> from the OTA <a href="/ahlaan-train-docs/admin/pricing/">Pricing &amp; Markup</a> engine (<code>PricingRule</code>). Custom markup is a deliberately simpler, flat configuration: no date/time/passenger/volume/target conditions.</p><hr><h2 id="how-custom-markup-rules-work" tabindex="-1">How Custom Markup Rules Work <a class="header-anchor" href="#how-custom-markup-rules-work" aria-label="Permalink to &quot;How Custom Markup Rules Work&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                 CUSTOM MARKUP RESOLUTION                          │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  1. Collect all ACTIVE custom markup rules                       │</span></span>
<span class="line"><span>│                        ↓                                          │</span></span>
<span class="line"><span>│  2. Keep rules whose route scope matches the request:           │</span></span>
<span class="line"><span>│     a null scope field is a wildcard (matches anything)         │</span></span>
<span class="line"><span>│                        ↓                                          │</span></span>
<span class="line"><span>│  3. Rank survivors:                                              │</span></span>
<span class="line"><span>│     ├─ most route-specific first (more non-null scope fields)   │</span></span>
<span class="line"><span>│     └─ then highest priority                                     │</span></span>
<span class="line"><span>│                        ↓                                          │</span></span>
<span class="line"><span>│  4. Apply the single top rule (PERCENTAGE or FIXED)             │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>A rule with <strong>no</strong> route scope (all of <code>originId</code>, <code>destinationId</code>, <code>tripClass</code>, <code>tripType</code> omitted) is the <strong>global default</strong>.</p><hr><h2 id="custom-markup-rule-fields" tabindex="-1">Custom Markup Rule Fields <a class="header-anchor" href="#custom-markup-rule-fields" aria-label="Permalink to &quot;Custom Markup Rule Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>✅</td><td>Display name (max 255 chars, no HTML)</td></tr><tr><td><code>description</code></td><td>string</td><td>-</td><td>Detailed description (max 1000 chars)</td></tr><tr><td><code>originId</code></td><td>string</td><td>-</td><td>Route origin location <strong>code</strong>, e.g. <code>DMX</code> (max 7 chars). This is the <code>Location.code</code>, <strong>not</strong> a Location UUID (contrast Tariff / Custom Route Price, where <code>originId</code> is a real Location id).</td></tr><tr><td><code>destinationId</code></td><td>string</td><td>-</td><td>Route destination location <strong>code</strong>, e.g. <code>MKX</code> (max 7 chars). The <code>Location.code</code>, <strong>not</strong> a Location UUID.</td></tr><tr><td><code>tripClass</code></td><td>enum</td><td>-</td><td><code>ECONOMY</code> or <code>BUSINESS</code></td></tr><tr><td><code>tripType</code></td><td>enum</td><td>-</td><td><code>ONE_WAY</code> or <code>ROUND_TRIP</code></td></tr><tr><td><code>markupType</code></td><td>enum</td><td>✅</td><td><code>PERCENTAGE</code> or <code>FIXED</code></td></tr><tr><td><code>markupValue</code></td><td>number</td><td>✅</td><td>Percentage (e.g. 15.5) or fixed amount (≥ 0)</td></tr><tr><td><code>currency</code></td><td>enum</td><td>⚠️</td><td><code>SAR</code> or <code>IDR</code>. <strong>Required when <code>markupType</code> is <code>FIXED</code></strong></td></tr><tr><td><code>priority</code></td><td>number</td><td>✅</td><td>Higher = applied first (0–999999)</td></tr><tr><td><code>isActive</code></td><td>boolean</td><td>✅</td><td>Enable/disable this rule</td></tr></tbody></table><hr><h2 id="base-url-authentication" tabindex="-1">Base URL &amp; Authentication <a class="header-anchor" href="#base-url-authentication" aria-label="Permalink to &quot;Base URL &amp; Authentication&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/v1</span></span></code></pre></div><p>All endpoints require a <strong>JWT token</strong> with the <strong>ADMIN</strong> role:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;your-admin-jwt-token&gt;</span></span></code></pre></div><hr><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><h3 id="_1-create-custom-markup-rule" tabindex="-1">1. Create Custom Markup Rule <a class="header-anchor" href="#_1-create-custom-markup-rule" aria-label="Permalink to &quot;1. Create Custom Markup Rule&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>POST /admin/custom-markup/rules</code></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Custom Mecca-Medina Markup&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Flat markup for custom bookings on this route&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;originId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DMX&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;destinationId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MKX&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tripClass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ECONOMY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;markupType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PERCENTAGE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;markupValue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;priority&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;isActive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Response:</strong> <code>201 Created</code> — the persisted rule (including generated <code>id</code>, <code>createdBy</code>, timestamps).</p><h3 id="_2-list-custom-markup-rules" tabindex="-1">2. List Custom Markup Rules <a class="header-anchor" href="#_2-list-custom-markup-rules" aria-label="Permalink to &quot;2. List Custom Markup Rules&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>GET /admin/custom-markup/rules</code></p><table tabindex="0"><thead><tr><th>Query Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>originId</code></td><td>string</td><td>Filter by route origin</td></tr><tr><td><code>destinationId</code></td><td>string</td><td>Filter by route destination</td></tr><tr><td><code>isActive</code></td><td>boolean</td><td>Filter by active status</td></tr><tr><td><code>page</code></td><td>number</td><td>Page number (default: 1)</td></tr><tr><td><code>limit</code></td><td>number</td><td>Items per page (default: 20)</td></tr></tbody></table><p><strong>Response:</strong> <code>200 OK</code> — <code>{ data: [...], meta: { total, page, limit, totalPages } }</code>.</p><h3 id="_3-get-custom-markup-rule-by-id" tabindex="-1">3. Get Custom Markup Rule by ID <a class="header-anchor" href="#_3-get-custom-markup-rule-by-id" aria-label="Permalink to &quot;3. Get Custom Markup Rule by ID&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>GET /admin/custom-markup/rules/:id</code> — <code>200 OK</code> or <code>404</code> if not found.</p><h3 id="_4-update-custom-markup-rule" tabindex="-1">4. Update Custom Markup Rule <a class="header-anchor" href="#_4-update-custom-markup-rule" aria-label="Permalink to &quot;4. Update Custom Markup Rule&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>PUT /admin/custom-markup/rules/:id</code> (all fields optional) — <code>200 OK</code>.</p><blockquote><p><strong>Partial updates respect the FIXED⇒currency rule.</strong> <code>markupType</code> and <code>currency</code> may be sent independently. The <code>currency</code>-required-for-<code>FIXED</code> constraint is re-asserted against the <strong>effective</strong> post-update rule (the persisted value for whichever field is omitted), so clearing <code>currency</code> on a <code>FIXED</code> rule — or flipping a currency-less rule to <code>FIXED</code> without supplying one — is rejected with <code>400</code>. Resend a valid <code>currency</code> (<code>SAR</code>/<code>IDR</code>) in the same request.</p></blockquote><h3 id="_5-deactivate-custom-markup-rule" tabindex="-1">5. Deactivate Custom Markup Rule <a class="header-anchor" href="#_5-deactivate-custom-markup-rule" aria-label="Permalink to &quot;5. Deactivate Custom Markup Rule&quot;">​</a></h3><p><strong>Endpoint:</strong> <code>DELETE /admin/custom-markup/rules/:id</code> — soft delete (<code>isActive: false</code>). Returns <code>{ &quot;success&quot;: true }</code>.</p><hr><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><h3 id="global-default-markup" tabindex="-1">Global default markup <a class="header-anchor" href="#global-default-markup" aria-label="Permalink to &quot;Global default markup&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/custom-markup/rules</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;token&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;name&quot;: &quot;Custom Default 10%&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;markupType&quot;: &quot;PERCENTAGE&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;markupValue&quot;: 10,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;priority&quot;: 0,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;isActive&quot;: true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><h3 id="route-specific-fixed-markup-overrides-the-default" tabindex="-1">Route-specific fixed markup (overrides the default) <a class="header-anchor" href="#route-specific-fixed-markup-overrides-the-default" aria-label="Permalink to &quot;Route-specific fixed markup (overrides the default)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/custom-markup/rules</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;token&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;name&quot;: &quot;DMX→MKX Fixed&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;originId&quot;: &quot;DMX&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;destinationId&quot;: &quot;MKX&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;markupType&quot;: &quot;FIXED&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;markupValue&quot;: 50,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;currency&quot;: &quot;SAR&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;priority&quot;: 100,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;isActive&quot;: true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>A request for <code>DMX → MKX</code> resolves to the route-specific rule (more specific); any other route falls back to the global default.</p><hr><h2 id="validation-rules" tabindex="-1">Validation Rules <a class="header-anchor" href="#validation-rules" aria-label="Permalink to &quot;Validation Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Validation</th><th>Error Message</th></tr></thead><tbody><tr><td><code>name</code></td><td>Max 255 chars, no HTML</td><td>&quot;Name must not exceed 255 characters&quot;</td></tr><tr><td><code>markupValue</code></td><td>≥ 0</td><td>&quot;Markup value cannot be negative&quot;</td></tr><tr><td><code>currency</code></td><td><code>SAR</code>/<code>IDR</code>, required for <code>FIXED</code> (re-asserted server-side on partial updates against the effective type)</td><td>&quot;currency is required when markupType is FIXED and must be SAR or IDR&quot;</td></tr><tr><td><code>originId</code>/<code>destinationId</code></td><td>Max 7 chars (location code, not a UUID)</td><td>&quot;Origin code must not exceed 7 characters&quot;</td></tr><tr><td><code>priority</code></td><td>0–999999</td><td>&quot;Priority cannot exceed 999999&quot;</td></tr></tbody></table><hr><h2 id="cache-propagation" tabindex="-1">Cache &amp; Propagation <a class="header-anchor" href="#cache-propagation" aria-label="Permalink to &quot;Cache &amp; Propagation&quot;">​</a></h2><p>Active rules are cached (<code>custom-markup:rules:active</code>, 15-minute TTL) for fast in-memory resolution. Creating, updating, or deactivating a rule flushes that cache so the change takes effect on the next resolution. This cache is <strong>scoped to this module only</strong> — it does <strong>not</strong> touch the OTA search cache, because custom markup is not part of OTA pricing.</p><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/admin/custom-tax/">Custom Tax Management</a></li><li><a href="/ahlaan-train-docs/admin/custom-route-price/">Custom Route Pricing</a></li><li><a href="/ahlaan-train-docs/admin/pricing/">Pricing &amp; Markup Management (OTA)</a></li><li><a href="/ahlaan-train-docs/admin/tax/">Tax Configuration (OTA)</a></li></ul>`,52)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
